import * as SplashScreen from "expo-splash-screen";
import { useEffect, useRef, useState } from "react";
import { Animated, Appearance, Easing, View } from "react-native";

import {
  BootScene,
  GLYPH_VISIBLE,
  useBootMotion,
  type Scheme,
} from "@/components/boot-scene";
import {
  getHeroBadge,
  subscribeHeroBadge,
  type Rect,
} from "@/features/boot/hero-badge";

/**
 * The boot sequence from the design ("Sequence": native splash → boot → Home, no visible cut).
 *
 *  1. The Android 12+ system splash plays a 1 s animated icon (assets/splash, generated by
 *     scripts/build-brand-assets.mjs). It is NOT allowed to end early: `SplashScreen.preventAutoHideAsync()`
 *     in `_layout.tsx` keeps it up, and this overlay hides it only once it has played.
 *  2. This overlay is mounted from the first React frame and paints that animation's LAST frame — same
 *     background, glyph, size and position — so when the splash goes the switch can't be seen.
 *  3. While pairing / theme / fonts settle (usually well under a second) the two arrows slide in opposite
 *     directions and, after 300 ms, a status line and an indeterminate bar fade in.
 *  4. Once the app is ready the glyph shrinks into Home's hero badge while the background fades to the
 *     themed surface (250 ms). With no badge to land on (unpaired -> pair-mac) it is a plain fade.
 *
 * The visuals live in boot-scene.tsx (shared with the dev preview screens, app/preview.tsx).
 *
 * Colours are FIXED, not the M3 theme (the design: dynamic colour starts at Home). The scheme is captured once
 * at mount: that is the *system* scheme, which is what the native splash used; the saved in-app mode is only
 * applied after `appearanceReady`, and re-reading it mid-flight would flip the frame we must match.
 */

/**
 * The AVD starts at process start and JS entry is ≥ 300 ms later, so ~700 ms after JS entry the 1 s intro
 * has finished on any realistic device. If the intro ever looks cut short on a slow device, raise this.
 */
const SPLASH_MIN_MS = 700;
const JS_START = Date.now();
/** Hide the splash anyway if the glyph images never report (never leave the app stuck on it). */
const SPLASH_FAILSAFE_MS = 2500;
/** How long to wait for Home to report its badge before settling for a plain fade. */
const BADGE_WAIT_MS = 500;
const LEAVE_MS = 250;

type Phase = "splash" | "boot" | "leaving" | "done";

export function BootOverlay({
  ready,
  expectBadge,
}: {
  /** pairing + theme + fonts are settled: the Stack underneath is mounted. */
  ready: boolean;
  /** The destination has the Home hero badge (a paired Mac); otherwise fade plainly. */
  expectBadge: boolean;
}) {
  const [scheme] = useState<Scheme>(() =>
    Appearance.getColorScheme() === "dark" ? "dark" : "light",
  );

  const [phase, setPhase] = useState<Phase>("splash");
  const [glyphReady, setGlyphReady] = useState(false);
  const glyphRef = useRef<View>(null);
  const rootRef = useRef<View>(null);

  const motion = useBootMotion(phase === "boot");
  // Two values driven in parallel: `leave` is eased (position / scale / background), `fade` is linear (the
  // glyph's dissolve). They can't be one value: the native driver ignores `easing` on `interpolate`, so an
  // eased look needs an eased timing, and a fade keyed to an eased value would start (and finish) too early,
  // making the glyph vanish short of the badge — seen on device.
  const [leave] = useState(() => new Animated.Value(0));
  const [fade] = useState(() => new Animated.Value(0));
  const [target, setTarget] = useState<{ dx: number; dy: number; scale: number } | null>(null);

  // 1 → 2: hide the native splash once the glyph has painted AND the intro has had time to play.
  useEffect(() => {
    if (phase !== "splash") return;
    let hidden = false;
    const handOff = () => {
      if (hidden) return;
      hidden = true;
      SplashScreen.hide();
      setPhase("boot");
    };
    const wait = glyphReady ? Math.max(0, SPLASH_MIN_MS - (Date.now() - JS_START)) : SPLASH_FAILSAFE_MS;
    const id = setTimeout(handOff, wait);
    const failsafe = setTimeout(handOff, SPLASH_FAILSAFE_MS);
    return () => {
      clearTimeout(id);
      clearTimeout(failsafe);
    };
  }, [phase, glyphReady]);

  // 4: leave once the app is ready; wait (briefly) for the hero badge's position if we expect one.
  useEffect(() => {
    if (phase !== "boot" || !ready) return;
    let started = false;
    let unsubscribe: (() => void) | undefined;
    let timeout: ReturnType<typeof setTimeout> | undefined;

    const begin = (badge: Rect | null) => {
      if (started) return;
      started = true;
      unsubscribe?.();
      if (timeout) clearTimeout(timeout);
      const run = (t: { dx: number; dy: number; scale: number } | null) => {
        setTarget(t);
        setPhase("leaving");
        Animated.parallel([
          Animated.timing(leave, {
            toValue: 1,
            duration: LEAVE_MS,
            easing: Easing.out(Easing.cubic),
            useNativeDriver: true,
          }),
          Animated.timing(fade, {
            toValue: 1,
            duration: LEAVE_MS,
            easing: Easing.linear,
            useNativeDriver: true,
          }),
        ]).start(() => setPhase("done"));
      };
      if (!badge || !glyphRef.current || !rootRef.current) return run(null);
      const glyph = glyphRef.current;
      // The badge rect comes from Compose in true window coordinates, but RN's `measureInWindow` is
      // shifted on Android (by the status-bar height, ~34 dp on a Galaxy S24: measured on device). This
      // overlay fills the whole window, so the root's own measured origin IS that shift — subtract it.
      rootRef.current.measureInWindow((rx, ry) => {
        glyph.measureInWindow((x, y, w, h) => {
          if (!w || !h) return run(null);
          run({
            dx: badge.x + badge.width / 2 - (x - rx + w / 2),
            dy: badge.y + badge.height / 2 - (y - ry + h / 2),
            // The badge draws its icon at ~46 % of the tile; shrink the glyph's visible width to that.
            scale: (badge.width * 0.46) / GLYPH_VISIBLE,
          });
        });
      });
    };

    if (!expectBadge) {
      begin(null);
    } else {
      const known = getHeroBadge();
      if (known) begin(known);
      else {
        unsubscribe = subscribeHeroBadge(begin);
        timeout = setTimeout(() => begin(null), BADGE_WAIT_MS);
      }
    }
    return () => {
      unsubscribe?.();
      if (timeout) clearTimeout(timeout);
    };
  }, [phase, ready, expectBadge, leave, fade]);

  if (phase === "done") return null;

  const bgOpacity = leave.interpolate({ inputRange: [0, 1], outputRange: [1, 0] });
  // Land first, then dissolve: by the time `fade` passes 0.7 the eased glyph is ≥97 % of its way there.
  const glyphOpacity = fade.interpolate({ inputRange: [0, 0.7, 1], outputRange: [1, 1, 0] });
  // The app name has no place in the hero badge: it is gone within the first ~35 % of the exit, before the
  // glyph has travelled far, so it never flies off as tiny text.
  const wordmarkOpacity = fade.interpolate({ inputRange: [0, 0.35], outputRange: [1, 0], extrapolate: "clamp" });
  const glyphTransform = target
    ? [
        { translateX: leave.interpolate({ inputRange: [0, 1], outputRange: [0, target.dx] }) },
        { translateY: leave.interpolate({ inputRange: [0, 1], outputRange: [0, target.dy] }) },
        { scale: leave.interpolate({ inputRange: [0, 1], outputRange: [1, target.scale] }) },
      ]
    : [];

  return (
    <BootScene
      scheme={scheme}
      motion={motion}
      rootRef={rootRef}
      glyphRef={glyphRef}
      onGlyphLoaded={() => setGlyphReady(true)}
      pointerEvents={phase === "leaving" ? "none" : "auto"}
      bgStyle={{ opacity: bgOpacity }}
      glyphStyle={{ opacity: glyphOpacity, transform: glyphTransform }}
      wordmarkStyle={{ opacity: wordmarkOpacity }}
    />
  );
}
